WITH enriched AS (SELECT id, plan, start_date, status, MIN(monthly_fee) OVER w_grp AS last7_min_monthly_fee, MAX(monthly_fee) OVER w_grp AS last7_max_monthly_fee, AVG(monthly_fee) OVER w_grp AS last7_avg_monthly_fee, SUM(monthly_fee) OVER (PARTITION BY YEAR(start_date) ORDER BY start_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_monthly_fee FROM subscriptions WHERE end_date > '2024-12-01' WINDOW w_grp AS (PARTITION BY customer_id ORDER BY end_date, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)), deduped AS (SELECT * FROM enriched QUALIFY ROW_NUMBER() OVER (PARTITION BY plan ORDER BY last7_min_monthly_fee DESC NULLS FIRST, id) = 1), deduped_subscriptions AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY status ORDER BY last7_min_monthly_fee DESC NULLS LAST) AS latest_rank FROM deduped) x WHERE latest_rank = 1), base AS (SELECT *, ROUND(running_monthly_fee * 100, 2) AS running_monthly_fee_scaled FROM deduped_subscriptions WHERE start_date > DATE '2023-02-24') SELECT plan, status, CASE WHEN running_monthly_fee >= 1242 THEN 'HIGH' ELSE 'LOW' END AS running_monthly_fee_tier, MIN(last7_max_monthly_fee) AS min_last7_max_monthly_fee, SUM(CASE WHEN status = 'PAUSED' THEN running_monthly_fee ELSE 0 END) AS paused_running_monthly_fee, ROUND(SUM(running_monthly_fee) / NULLIF(COUNT(CASE WHEN plan = 'premium' THEN 1 END), 0), 2) AS running_monthly_fee_per_premium, COUNT(CASE WHEN plan = 'standard' THEN 1 END) AS standard_count, PERCENTILE_APPROX(running_monthly_fee, 0.9) AS running_monthly_fee_p90, COUNT(*) FILTER (WHERE plan = 'premium') AS premium_rows FROM base GROUP BY plan, status, running_monthly_fee_tier HAVING standard_count < 1000
